MERGE `{{params.project_name}}.semantics_central.CarTransits` final
USING (
{{range_query}}
) staging
ON final.transit_id = staging.transit_id
WHEN MATCHED THEN
UPDATE SET
final.transit_job_id = staging.transit_job_id,
final.car_id = staging.car_id,
final.country_id = staging.country_id,
final.transit_type = staging.transit_type,
final.transit_status = staging.transit_status,
final.transit_start_location = staging.transit_start_location,
final.transit_end_location = staging.transit_end_location,
final.transit_driver = staging.transit_driver,
final.transit_driver_id = staging.transit_driver_id,
final.transit_driver_company = staging.transit_driver_company,
final.start_mileage = staging.start_mileage,
final.end_mileage = staging.end_mileage,
final.transit_comment = staging.transit_comment,
final.transit_start_time = staging.transit_start_time,
final.transit_end_time = staging.transit_end_time,
final.transit_created_at = staging.transit_created_at,
final.transit_created_by_id = staging.transit_created_by_id,
final.transit_created_by = staging.transit_created_by,
final.transit_last_modified = staging.transit_last_modified,
final.transit_last_modified_by_id = staging.transit_last_modified_by_id,
final.transit_last_modified_by = staging.transit_last_modified_by,
final.deleted_at = staging.deleted_at,
final.deleted_by_id = staging.deleted_by_id,
final.deleted_by = staging.deleted_by
WHEN NOT MATCHED THEN
INSERT (
transit_id,
transit_job_id,
car_id,
country_id,
transit_type,
transit_status,
transit_start_location,
transit_end_location,
transit_driver,
transit_driver_id,
transit_driver_company,
start_mileage,
end_mileage,
transit_comment,
transit_start_time,
transit_end_time,
transit_created_at,
transit_created_by_id,
transit_created_by,
transit_last_modified,
transit_last_modified_by_id,
transit_last_modified_by,
deleted_at,
deleted_by_id,
deleted_by
) VALUES (
staging.transit_id,
staging.transit_job_id,
staging.car_id,
staging.country_id,
staging.transit_type,
staging.transit_status,
staging.transit_start_location,
staging.transit_end_location,
staging.transit_driver,
staging.transit_driver_id,
staging.transit_driver_company,
staging.start_mileage,
staging.end_mileage,
staging.transit_comment,
staging.transit_start_time,
staging.transit_end_time,
staging.transit_created_at,
staging.transit_created_by_id,
staging.transit_created_by,
staging.transit_last_modified,
staging.transit_last_modified_by_id,
staging.transit_last_modified_by,
staging.deleted_at,
staging.deleted_by_id,
staging.deleted_by
)